//! Durable measured sessions and store totals. Measured sessions are never sent in this step.

use serde::{Deserialize, Serialize};

/// All times are Unix seconds UTC. Identifiers are generated by the platform, never by core.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Session {
    pub id: String,
    pub account_id: String,
    pub entry_key: String,
    pub game_id: Option<u64>,
    pub source: String,
    pub platform_id: u32,
    pub started_at: i64,
    pub checkpoint_at: i64,
    pub ended_at: Option<i64>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Total {
    pub account_id: String,
    pub entry_key: String,
    pub total_seconds: i64,
    pub last_played_at: Option<i64>,
    pub accepted_game_id: Option<u64>,
    pub accepted_seconds: Option<i64>,
    pub rejected_seconds: Option<i64>,
}

pub mod submitter;

/// One absolute provider total, never a measured session or a delta.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Submission {
    pub game_id: u64,
    pub source: String,
    pub total_seconds: i64,
    pub last_played_at: Option<i64>,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum SubmitError {
    #[error("GameNode rejected the session")]
    Unauthorized,
    #[error("GameNode rejected the playtime total")]
    Rejected,
    #[error("playtime could not be sent")]
    Unavailable,
}

/// One preference for this PC; unsupported stores always use the internal tracker.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum PlaytimeSource {
    #[default]
    Store,
    Internal,
}
impl PlaytimeSource {
    pub fn parse(value: Option<&str>) -> Self {
        if value == Some("internal") {
            Self::Internal
        } else {
            Self::Store
        }
    }
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Store => "store",
            Self::Internal => "internal",
        }
    }
    pub fn uses_counter(self, supported: bool) -> bool {
        self == Self::Store && supported
    }
}

/// Display data for one entry. Unknown store data is different from a known zero.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PlaytimeView {
    pub seconds: Option<i64>,
    pub source: PlaytimeSource,
}

/// Select one account's history without adding store totals to measured sessions.
pub fn view_for_entry(
    account: &str,
    key: &str,
    source: PlaytimeSource,
    totals: &[Total],
    sessions: &[Session],
    now: i64,
) -> PlaytimeView {
    let seconds = match source {
        PlaytimeSource::Store => totals
            .iter()
            .find(|t| t.account_id == account && t.entry_key == key)
            .map(|t| t.total_seconds)
            .filter(|seconds| *seconds >= 0),
        PlaytimeSource::Internal => Some(
            sessions
                .iter()
                .filter(|s| s.account_id == account && s.entry_key == key)
                .map(|s| {
                    s.ended_at
                        .unwrap_or(now)
                        .saturating_sub(s.started_at)
                        .clamp(0, 86400)
                })
                .fold(0i64, i64::saturating_add),
        ),
    };
    PlaytimeView { seconds, source }
}

